pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address user, uint unlockTime, uint deposit, uint collectAmount) public {
        // Bound inputs to reasonable ranges
        unlockTime = bound(unlockTime, 0, 365 days);
        deposit = bound(deposit, 1 ether, 100 ether);
        collectAmount = bound(collectAmount, 0, deposit);
        vm.assume(collectAmount >= 1 ether); // MinSum is 1 ether

        // Setup: fund user and put Ether into contract
        vm.deal(user, deposit);
        vm.prank(user);
        c.Put{value: deposit}(block.timestamp + unlockTime);

        // Prepare for Collect call: set time exactly at unlock time
        uint unlockTimestamp = block.timestamp + unlockTime;
        vm.warp(unlockTimestamp);

        // Call Collect and check if it reverts (should not revert in correct version)
        vm.prank(user);
        (bool success, ) = address(c).call{value: 0}(abi.encodeWithSignature("Collect(uint256)", collectAmount));

        // The reference should revert because block.timestamp == acc.unlockTime (not strictly greater)
        // The buggy version would succeed but that's wrong
        assertTrue(success == false, "Collect should revert when timestamp equals unlockTime");
    }
}

