pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 unlockDelta, uint256 balance, uint256 amount) public {
        // Ensure sufficient balance and valid amounts
        vm.assume(balance >= c.MinSum() && balance >= amount && amount > 0);
        // Ensure unlock time is exactly block.timestamp
        uint256 unlockTime = block.timestamp + (unlockDelta % 1); // force unlockDelta % 1 = 0, so unlockTime == block.timestamp
        vm.assume(unlockTime == block.timestamp);

        // Setup: fund the contract and set caller's deposit
        vm.deal(address(c), balance);
        vm.prank(caller);
        (bool successPut, ) = address(c).call{value: balance}(abi.encodeWithSignature("Put(uint256)", unlockTime));
        require(successPut, "Put failed");

        // Now call Collect with amount
        bool reverted;
        try c.Collect(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // The correct behavior: should revert because condition requires block.timestamp > acc.unlockTime, not >=.
        assertTrue(reverted, "Collect should have reverted when block.timestamp == unlockTime");
    }
}

