pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this)); }
    function testFuzz_property(address caller, uint256 putAmount, uint256 unlockTimeOffset, uint256 withdrawAmount) public {
        vm.assume(caller != address(0));
        vm.assume(caller != address(this));
        putAmount = bound(putAmount, 1 ether, 1000 ether);
        unlockTimeOffset = bound(unlockTimeOffset, 0, 1000);
        withdrawAmount = bound(withdrawAmount, 1 ether, putAmount);

        vm.deal(caller, putAmount);
        vm.prank(caller);
        c.Put(block.timestamp + unlockTimeOffset);

        vm.warp(block.timestamp + unlockTimeOffset + 1);

        uint256 balanceBefore = c.Acc(caller).balance;

        vm.prank(caller);
        (bool success, ) = address(c).call{gas: 100000}(abi.encodeWithSignature("Collect(uint256)", withdrawAmount));

        if (success && balanceBefore >= withdrawAmount) {
            uint256 balanceAfter = c.Acc(caller).balance;
            assertTrue(balanceAfter == balanceBefore - withdrawAmount, "Balance should be decreased by exactly withdrawAmount");
        } else {
            assertTrue(true);
        }
    }
}

