pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this)); }

    function testFuzz_property(address caller, uint256 depositAmount, uint256 unlockTime, uint256 withdrawAmount) public {
        vm.assume(caller != address(0) && caller != address(c));
        depositAmount = bound(depositAmount, 0, 1 ether);
        unlockTime = bound(unlockTime, 0, block.timestamp + 1000);
        withdrawAmount = bound(withdrawAmount, 0, 1 ether);

        // Fund the caller and make a deposit
        vm.deal(caller, depositAmount * 2);
        vm.prank(caller);
        c.Put{value: depositAmount}(unlockTime);

        // Record states before Collect
        (uint256 balanceBefore, ) = c.Acc(caller);
        uint256 contractBalBefore = address(c).balance;

        // Attempt Collect
        vm.prank(caller);
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.Collect.selector, withdrawAmount));

        if (success) {
            (uint256 balanceAfter, ) = c.Acc(caller);
            uint256 contractBalAfter = address(c).balance;
            // Rule: sum of caller's Acc balance and contract balance unchanged
            assertTrue(balanceAfter + contractBalAfter == balanceBefore + contractBalBefore);
        } else {
            // If revert, rule is vacuously true
            assertTrue(true);
        }
    }
}

